// Settling a claim both reports a result and draws down the policy's cap, so
// it returns the policy as it stands afterwards rather than mutating in place.
interface Settlement {
  result: ClaimResult;
  policy: Policy;
}

const claim = ({ incident }: ClaimStep, policy: Policy): Settlement => {
  const payout = incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage),
    0,
  );

  const remainingCap = policy.remainingCap - payout;

  return {
    result: { payout: Math.floor(payout), remainingCap },
    policy: { ...policy, remainingCap },
  };
};

const { result, policy } = claim(step, policies.get(step.policy)!);

results.push(result);
policies.set(step.policy, policy);
